package hestia

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// CustomTemplate is the one and only template generated by this tool. Every
// site that uses custom locations points to it, whatever stock template it
// came from: the per-site differences live in sites/<domain>/locations.conf.
const CustomTemplate = "tui"

// Template is a Hestia web template (a .tpl + .stpl pair).
type Template struct {
	Name   string
	Custom bool // the generated "tui" template
}

// Templates lists the usable templates (both .tpl and .stpl present).
func (e *Env) Templates() ([]Template, error) {
	dir := e.TemplateDir()
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	have := map[string]int{}
	for _, en := range ents {
		n := en.Name()
		switch {
		case strings.HasSuffix(n, ".stpl"):
			have[strings.TrimSuffix(n, ".stpl")] |= 2
		case strings.HasSuffix(n, ".tpl"):
			have[strings.TrimSuffix(n, ".tpl")] |= 1
		}
	}
	var out []Template
	for n, m := range have {
		if m != 3 || n == "suspended" {
			continue
		}
		out = append(out, Template{Name: n, Custom: IsCustom(n)})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// StockTemplates returns the templates that ship with Hestia (everything but "tui").
func (e *Env) StockTemplates() ([]Template, error) {
	all, err := e.Templates()
	if err != nil {
		return nil, err
	}
	var out []Template
	for _, t := range all {
		if !t.Custom {
			out = append(out, t)
		}
	}
	return out, nil
}

// includeBlock is what replaces the site-specific part inside a template.
// %domain% is substituted by Hestia itself when it builds the domain config.
func (e *Env) includeBlock() string {
	// "locations.con[f]" is a glob that matches exactly locations.conf. nginx
	// silently ignores a glob without matches, whereas a missing plain include
	// would make `nginx -t` fail for every site on the server.
	return "\t# ---- hestia-nginx-tui: everything site specific (root, locations, ...) ----\n" +
		"\tinclude " + e.StateDir + "/sites/%domain%/locations.con[f];\n"
}

func (e *Env) banner() string {
	return "#=========================================================================#\n" +
		"# GENERATED by hestia-nginx-tui - DO NOT EDIT, regenerated on every apply.\n" +
		"# This template only holds the fixed Hestia skeleton. Root, locations and\n" +
		"# every other site specific directive live in\n" +
		"#   " + e.StateDir + "/sites/%domain%/locations.conf\n" +
		"#=========================================================================#\n\n"
}

func (e *Env) readStock(name, ext string) (string, error) {
	b, err := os.ReadFile(filepath.Join(e.TemplateDir(), name+"."+ext))
	return string(b), err
}

// skeletonBase is the stock template the fixed skeleton is derived from. The
// "default" template ships with every Hestia, so the skeleton always matches
// the installed version (ssl directives, anti-replay, ...).
const skeletonBase = "default"

// SeedLocations returns the site-specific part of a stock template (root,
// index, locations, ...), ready to pre-fill a site's locations file.
func (e *Env) SeedLocations(base string) (string, error) {
	if !ValidName(base) || IsCustom(base) {
		return "", fmt.Errorf("invalid base template %q", base)
	}
	raw, err := e.readStock(base, "tpl")
	if err != nil {
		return "", err
	}
	sp, err := SplitServer(raw, "")
	if err != nil {
		return "", fmt.Errorf("%s.tpl: %w", base, err)
	}
	if sp.Count == 0 {
		return "", fmt.Errorf("%s.tpl has nothing site specific to extract", base)
	}
	return sp.Seed, nil
}

// StockWarnings returns caveats about a stock template that the generic
// skeleton cannot reproduce (currently HTTP/3).
func (e *Env) StockWarnings(base string) []string {
	var w []string
	if raw, err := e.readStock(base, "stpl"); err == nil && (strings.Contains(raw, "quic") || strings.Contains(raw, "http3")) {
		w = append(w, "the stock \""+base+"\" template enables HTTP/3 (quic); the generic tui template does not")
	}
	return w
}

// EnsureCustomTemplate (re)generates tui.tpl and tui.stpl from the skeleton of
// the installed default template, so they follow Hestia updates.
func (e *Env) EnsureCustomTemplate() (string, error) {
	inc := e.includeBlock()
	for _, ext := range []string{"tpl", "stpl"} {
		raw, err := e.readStock(skeletonBase, ext)
		if err != nil {
			return "", fmt.Errorf("cannot read the %q template to build the skeleton: %w", skeletonBase, err)
		}
		sp, err := SplitServer(raw, inc)
		if err != nil {
			return "", fmt.Errorf("%s.%s: %w", skeletonBase, ext, err)
		}
		if err := writeFileAtomic(filepath.Join(e.TemplateDir(), CustomTemplate+"."+ext), []byte(e.banner()+sp.Template), 0o644); err != nil {
			return "", err
		}
	}
	return CustomTemplate, nil
}

// ---------------------------------------------------------------------------
// per-site metadata: which stock template the locations were seeded from

func (e *Env) basePath(domain string) string { return filepath.Join(e.SiteDir(domain), "base") }

// ReadBase returns the stock template the site's locations were seeded from.
func (e *Env) ReadBase(domain string) string {
	b, err := os.ReadFile(e.basePath(domain))
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(b))
}

// RecordBase remembers which stock template a site's locations came from.
func (e *Env) RecordBase(domain, base string) { e.saveBase(domain, base) }

func (e *Env) saveBase(domain, base string) {
	if base != "" {
		_ = writeFileAtomic(e.basePath(domain), []byte(base+"\n"), 0o644)
	}
}

// ReseedLocations replaces a site's locations with those of a stock template
// (the previous text stays in history/). Nothing is applied.
func (e *Env) ReseedLocations(s Site, base string) error {
	seed, err := e.SeedLocations(base)
	if err != nil {
		return err
	}
	if err := e.SaveLocations(s, seed); err != nil {
		return err
	}
	e.saveBase(s.Domain, base)
	return nil
}

// ---------------------------------------------------------------------------
// applying

func (e *Env) changeTemplate(s Site, tpl string) (string, error) {
	return e.Run(120*time.Second, filepath.Join(e.BinDir(), "v-change-web-domain-tpl"), s.User, s.Domain, tpl, "yes")
}

// ApplyCustom renders the saved locations, makes sure the tui template exists
// and applies it with `v-change-web-domain-tpl USER DOMAIN tui yes`. When the
// site has no saved locations yet they are pre-filled from seedBase.
// If nginx rejects the result, everything is rolled back.
func (e *Env) ApplyCustom(s Site, seedBase string) (string, error) {
	var log strings.Builder
	step := func(l string) { log.WriteString(l) }

	if !ValidName(s.Domain) || !ValidName(s.User) {
		return "", errors.New("invalid user/domain")
	}
	src, ok := e.ReadLocations(s.Domain)
	if !ok {
		if seedBase == "" {
			return "", errors.New("this site has no saved locations yet: open the editor first")
		}
		if err := e.ReseedLocations(s, seedBase); err != nil {
			return "", err
		}
		src, _ = e.ReadLocations(s.Domain)
		step("✓ locations pre-filled from the \"" + seedBase + "\" template\n")
	}
	name, err := e.EnsureCustomTemplate()
	if err != nil {
		return "", err
	}
	step("✓ template " + name + ".tpl/.stpl generated\n")

	prev, hadPrev := []byte(nil), false
	if b, err := os.ReadFile(e.LocPath(s.Domain)); err == nil {
		prev, hadPrev = b, true
	}
	restore := func() {
		if hadPrev {
			_ = writeFileAtomic(e.LocPath(s.Domain), prev, 0o644)
		} else {
			_ = os.Remove(e.LocPath(s.Domain))
		}
	}
	if err := writeFileAtomic(e.LocPath(s.Domain), []byte(e.Render(s, src)), 0o644); err != nil {
		return log.String(), err
	}
	step("✓ " + e.LocPath(s.Domain) + " rendered\n")

	already := s.Template == name
	if already {
		// The vhost already includes the file: validate before touching anything.
		l, err := e.NginxTest()
		step(l)
		if err != nil {
			restore()
			step("✗ nginx -t failed: previous locations restored, nothing was applied\n")
			return log.String(), fmt.Errorf("nginx rejected the new locations")
		}
	}
	l, err := e.changeTemplate(s, name)
	step(l)
	if err != nil {
		restore()
		if !already {
			l2, _ := e.changeTemplate(s, s.Template)
			step(l2)
		}
		return log.String(), fmt.Errorf("v-change-web-domain-tpl failed")
	}
	l, err = e.NginxTest()
	step(l)
	if err != nil {
		restore()
		l2, _ := e.changeTemplate(s, s.Template)
		step("✗ nginx -t failed after apply: reverting to " + s.Template + "\n" + l2)
		return log.String(), fmt.Errorf("nginx rejected the configuration; reverted")
	}
	step("✓ applied " + name + " to " + s.Domain + " (nginx reloaded)\n")
	return log.String(), nil
}

// ApplyStock switches a site to a stock template.
func (e *Env) ApplyStock(s Site, tpl string) (string, error) {
	if !ValidName(s.Domain) || !ValidName(s.User) || !ValidName(tpl) {
		return "", errors.New("invalid user/domain/template")
	}
	var log strings.Builder
	l, err := e.changeTemplate(s, tpl)
	log.WriteString(l)
	if err != nil {
		return log.String(), fmt.Errorf("v-change-web-domain-tpl failed")
	}
	l, err = e.NginxTest()
	log.WriteString(l)
	if err != nil {
		l2, _ := e.changeTemplate(s, s.Template)
		log.WriteString("✗ nginx -t failed: reverting to " + s.Template + "\n" + l2)
		return log.String(), fmt.Errorf("nginx rejected the configuration; reverted")
	}
	log.WriteString("✓ template " + tpl + " applied to " + s.Domain + "\n")
	return log.String(), nil
}

// RenderAll re-renders every site that uses the tui template (useful after a
// PHP version change, which moves %backend_lsnr%) and reloads nginx once.
func (e *Env) RenderAll() (string, error) {
	sites, err := e.LoadSites()
	if err != nil {
		return "", err
	}
	var log strings.Builder
	n := 0
	for _, s := range sites {
		if !IsCustom(s.Template) {
			continue
		}
		src, ok := e.ReadLocations(s.Domain)
		if !ok {
			continue
		}
		if err := writeFileAtomic(e.LocPath(s.Domain), []byte(e.Render(s, src)), 0o644); err != nil {
			return log.String(), err
		}
		fmt.Fprintf(&log, "✓ %s\n", s.Domain)
		n++
	}
	if n == 0 {
		return "no site uses the tui template\n", nil
	}
	l, err := e.NginxTest()
	log.WriteString(l)
	if err != nil {
		return log.String(), err
	}
	l, err = e.NginxReload()
	log.WriteString(l)
	return log.String(), err
}
